      return [...conns.entries()]
        .filter(([id, s]) => s === sub && marks.get(id)?.deck === true)
        .map(([connectionId]) => ({ connectionId, ...(marks.get(connectionId) ?? {}) }));
    },
    async disconnect(id) {
      conns.delete(id);
      marks.delete(id);
      for (const set of watches.values()) set.delete(id);
    },
  };
